const b = $('Estimate Webhook').first().json.body;
const body = (b && typeof b === 'object' && !Array.isArray(b)) ? b : null;
let error = null;
if (!body) error = 'Body must be a JSON object.';
else if (!Array.isArray(body.items) || body.items.length === 0) error = 'items must be a non-empty array.';
else {
  for (let i = 0; i < body.items.length; i++) {
    const it = body.items[i];
    if (!it || typeof it !== 'object' || Array.isArray(it) || typeof it.service !== 'string' || it.service.trim() === '') {
      error = 'items[' + i + '].service must be a non-empty string.';
      break;
    }
  }
}
if (error) return [{ json: { valid: false, error } }];
return [{ json: {
  valid: true,
  job_name: typeof body.job_name === 'string' && body.job_name.trim() ? body.job_name.trim() : '(unnamed job)',
  notes: typeof body.notes === 'string' ? body.notes : '',
  items: body.items.map(it => ({ service: it.service, quantity: it.quantity === undefined ? null : it.quantity }))
