// Port of estimator/estimate.py (same rules, same messages). Exact decimal math with BigInt.
const req = $('Validate Request').first().json;
const pText = v => (v && Array.isArray(v.title || v.rich_text)) ? (v.title || v.rich_text).map(t => t.plain_text).join('') : '';
const rules = [];
for (const it of $input.all()) {
  const p = it.json.properties;
  if (!p) continue;
  rules.push({
    id: it.json.id,
    notes: pText(p['Notes']),
    service: pText(p['Service']),
    category: p['Category']?.select?.name ?? null,
    base_rate: p['Base Rate']?.number ?? null,
    unit: p['Unit']?.select?.name ?? null,
    minimum_charge: p['Minimum Charge']?.number ?? null,
