}
const P10 = n => 10n ** BigInt(n);
function toDec(v) {
  if (v === null || v === undefined || typeof v === 'boolean') return null;
  if (typeof v === 'number' && !Number.isFinite(v)) return null;
  if (typeof v !== 'number' && typeof v !== 'string') return null;
  const m = String(v).trim().match(/^\+?(\d+)(?:\.(\d*))?(?:[eE]([+-]?\d+))?$|^\+?\.(\d+)(?:[eE]([+-]?\d+))?$/);
  if (!m) return null;
  const ip = m[1] !== undefined ? m[1] : '', fp = m[1] !== undefined ? (m[2] || '') : m[4];
  const ex = parseInt((m[1] !== undefined ? m[3] : m[5]) || '0', 10);
  let n = BigInt(ip + fp || '0'), s = fp.length - ex;
  if (s < 0) { n *= P10(-s); s = 0; }
