}
const align = (a, b) => { const s = Math.max(a.s, b.s); return [a.n * P10(s - a.s), b.n * P10(s - b.s), s]; };
const add = (a, b) => { const [x, y, s] = align(a, b); return { n: x + y, s }; };
const mul = (a, b) => ({ n: a.n * b.n, s: a.s + b.s });
const lt = (a, b) => { const [x, y] = align(a, b); return x < y; };
const gt = (a, b) => lt(b, a);
function money(a) { // round half up to cents
  if (a.s <= 2) return { n: a.n * P10(2 - a.s), s: 2 };
  const d = P10(a.s - 2); let q = a.n / d;
  if ((a.n % d) * 2n >= d) q += 1n;
  return { n: q, s: 2 };
}
function fmtMoney(a) {
  const m = money(a), t = m.n.toString().padStart(3, '0');
  return t.slice(0, -2) + '.' + t.slice(-2);
}
function fmtNum(a) {
  let t = a.n.toString(), s = a.s;
  while (s > 0 && t.endsWith('0')) { t = t.slice(0, -1); s--; }
  if (s === 0) return t;
  t = t.padStart(s + 1, '0');
  return t.slice(0, -s) + '.' + t.slice(-s);
