const key = n => String(n ?? '').split(/\s+/).filter(Boolean).join(' ').toLowerCase();
const UNITS = { 'per sqft': 'Per Sqft', 'per room': 'Per Room', 'flat rate': 'Flat Rate', 'per hour': 'Per Hour' };
const CATS = { 'interior': 'Interior', 'exterior': 'Exterior', 'add-on': 'Add-On' };
const PRIMARY = new Set(['Interior', 'Exterior']);

const missing = [], warnings = [], lines = [], jl = [], ruleNotes = [];
const active = new Map(), inactive = new Set();
