req.items.forEach((item, idx) => {
  const pos = idx + 1, service = item.service;
  const label = "'" + service + "' (item " + pos + ')';
  const k = key(service);
  if (!k) { missing.push('Item ' + pos + ' has no service name; line excluded.'); return; }
  const matches = active.get(k) || [];
  if (!matches.length) {
    missing.push(inactive.has(k)
      ? 'Service ' + label + ' has only inactive rules; line excluded.'
      : 'No active rule for service ' + label + '; line excluded.');
    return;
  }
  if (matches.length > 1) { missing.push('Multiple active rules match service ' + label + '; cannot choose; line excluded.'); return; }
  const rule = matches[0];
  const unit = UNITS[String(rule.unit ?? '').trim().toLowerCase()];
  if (!unit) { missing.push('Rule for ' + label + ' has unknown unit ' + JSON.stringify(rule.unit) + '; line excluded.'); return; }
  const category = CATS[String(rule.category ?? '').trim().toLowerCase()];
  if (!category) { missing.push('Rule for ' + label + ' has unknown category ' + JSON.stringify(rule.category) + '; line excluded.'); return; }
  if (rule.base_rate === null || rule.base_rate === undefined) { missing.push('Rule for ' + label + ' has no base_rate; line excluded.'); return; }
  const rate = toDec(rule.base_rate);
  if (!rate) { missing.push('Rule for ' + label + ' has invalid base_rate ' + JSON.stringify(rule.base_rate) + '; line excluded.'); return; }
  let qty;
  if (unit === 'Flat Rate') {
    if (item.quantity !== null && item.quantity !== undefined) warnings.push('Quantity for flat-rate service ' + label + ' ignored; treated as 1.');
    qty = { n: 1n, s: 0 };
  } else {
    if (item.quantity === null || item.quantity === undefined) { missing.push('Quantity missing for ' + label + ' (' + unit + '); line excluded.'); return; }
    qty = toDec(item.quantity);
    if (!qty) { missing.push('Invalid quantity ' + JSON.stringify(item.quantity) + ' for ' + label + '; line excluded.'); return; }
  }
  let ruleMin = null;
  if (PRIMARY.has(category) && rule.minimum_charge !== null && rule.minimum_charge !== undefined) {
    ruleMin = toDec(rule.minimum_charge);
    if (!ruleMin) { missing.push('Invalid minimum_charge ' + JSON.stringify(rule.minimum_charge) + ' for ' + label + '; line excluded.'); return; }
  }
  const amount = money(mul(rate, qty));
