  const lm = isPrim && ruleMin ? money(ruleMin) : null;
  const lApplied = !!(lm && lt(amount, lm));
  jl.push({ service: rule.service, rule_id: rule.id, category, unit, base_rate: Number(fmtMoney(rate)), quantity: Number(fmtNum(qty)),
    computed: Number(fmtMoney(amount)), minimum_charge: lm ? Number(fmtMoney(lm)) : 0, minimum_applied: lApplied,
    line_total: Number(fmtMoney(lApplied ? lm : amount)) });
