  if (PRIMARY.has(category)) {
    hasPrimary = true;
    primary = add(primary, amount);
    if (ruleMin && (minimum === null || gt(ruleMin, minimum))) minimum = ruleMin;
  } else addon = add(addon, amount);
});

if (!hasPrimary && addon.n > 0n) missing.push('Add-On requested with no main Interior/Exterior service.');
const minApplied = hasPrimary && minimum !== null && lt(primary, minimum);
const primaryTotal = minApplied ? minimum : primary;
const total = missing.length ? null : fmtMoney(add(money(primaryTotal), addon));
const estimate = {
  job_name: req.job_name,
  lines,
  subtotal: fmtMoney(add(primary, addon)),
  minimum_applied: !!minApplied,
  minimum_charge: (hasPrimary && minimum !== null) ? fmtMoney(minimum) : null,
  total,
  missing,
  warnings,
  notes: req.notes
